public FrmRemeshingParametersRule(Controller controller,string name=null,string[] parts=null):base(controller,null) { var meshParts=controller.GetModelPartNames();var mp=controller.GetPartDefaultMeshingParameters(meshParts);
RemeshingParameters=new RemeshingParameters("",RegionTypeEnum.Selection,mp);var mmg=controller.GetPartDefaultShellMmg(meshParts);if(mmg!=null)RemeshingParameters.Hausdorff=mmg.Hausdorff;
_viewRemeshingParameters.PopulateDropDownLists(controller.GetUserElementSetNames());SelectedObject=_viewRemeshingParameters; }
public RemeshingParameters RemeshingParameters
        {
            get { return _viewRemeshingParameters.GetBase(); }
            set { _viewRemeshingParameters = new ViewRemeshingParameters(value.DeepClone()); }
        }
protected override void OnApply(bool onOkAddNew)
        {
            _highlightEnabled = false;
            //
            CheckRemeshingParameters();
            //
            _controller.RemeshElementsCommand(RemeshingParameters);
            // If all is successful close the ItemSetSelectionForm - except for OKAddNew
            if (onOkAddNew)
            {
                _prevRemeshingParameters = RemeshingParameters.DeepClone();
                // The remeshed elements were replaced by elements with new ids, so the selection
                // that created them can no longer be resolved and must not be reselected
                ClearRegionSelection(_prevRemeshingParameters);
            }
            else ; /* Toolkit presentation. */
        }
private void CheckRemeshingParameters()
        {
            _viewRemeshingParameters = (ViewRemeshingParameters)SelectedObject;
            //
            if (_viewRemeshingParameters == null) throw new CaeException("No remeshing was selected.");
            //
            if (RemeshingParameters.RegionType == RegionTypeEnum.Selection &&
                (RemeshingParameters.CreationIds == null || RemeshingParameters.CreationIds.Length == 0))
                throw new CaeException("The element set for remeshing selection must contain at least one item.");
        }
private void ClearRegionSelection(RemeshingParameters remeshingParameters)
        {
            if (remeshingParameters.RegionType != RegionTypeEnum.Selection) return;
            //
            remeshingParameters.CreationIds = null;
            remeshingParameters.CreationData = new Selection();
            remeshingParameters.CreationData.SelectItem = vtkSelectItem.Element;
        }
public override void Preview(){CheckRemeshingParameters();_controller.RemeshElements(RemeshingParameters,true);}
