// Source PrePoMax/Forms/21_FEModel/FrmSplitPartMeshUsingSurface.cs SHA256 cd0efdafaedb2e331a207abca933b9b6d06e506e14ca0e311ee6a4e4afcc4a25
public sealed class FrmSplitPartMeshUsingSurfaceRule : GeometryFormRule {
ViewSplitPartMeshData _viewSplitPartMeshData;SplitPartMeshData _prevSplitPartMeshData;bool _highlightEnabled;
public FrmSplitPartMeshUsingSurfaceRule(Controller controller,string name=null,string[] parts=null):base(controller,null) { SplitPartMeshData=new SplitPartMeshData(RegionTypeEnum.Selection,"",RegionTypeEnum.Selection,"");
_viewSplitPartMeshData.PopulateDropDownLists(controller.GetModelPartNames(),controller.GetUserSurfaceNames());SelectedObject=_viewSplitPartMeshData; }
public SplitPartMeshData SplitPartMeshData
        {
            get { return _viewSplitPartMeshData.GetBase(); }
            set { _viewSplitPartMeshData = new ViewSplitPartMeshData(value.DeepClone()); }
        }protected override void OnApply(bool onOkAddNew)
        {
            _highlightEnabled = false;
            //
            CheckSplitPartMeshData(true, out _);
            //
            _controller.SplitPartMeshUsingSurfaceCommand(SplitPartMeshData);
            // If all is successful close the ItemSetSelectionForm - except for OKAddNew
            if (onOkAddNew) _prevSplitPartMeshData = SplitPartMeshData.DeepClone();
            else ; /* Toolkit presentation. */
        }private void CheckSplitPartMeshData(bool throwExceptions, out BasePart basePart)
        {
            basePart = null;
            //
            try
            {
                if (SplitPartMeshData == null) { throw new NotSupportedException(); }
                else if (SplitPartMeshData is SplitPartMeshData sp)
                {
                    CheckBasePartMeshData(throwExceptions, out basePart);
                    // Splitter surface
                    if (sp.SlaveRegionType == RegionTypeEnum.Selection &&
                        (sp.SplitterSurfaceCreationIds == null || sp.SplitterSurfaceCreationIds.Length == 0))
                        throw new CaeException("The splitter surface region must contain at least one item.");
                }
            }
            catch (Exception ex)
            {
                if (throwExceptions) throw ex;
            }
        }private void CheckBasePartMeshData(bool throwExceptions, out BasePart basePart)
        {
            basePart = null;
            //
            try
            {
                if (SplitPartMeshData == null) { throw new NotSupportedException(); }
                else if (SplitPartMeshData is SplitPartMeshData sp)
                {
                    // Base part
                    if (sp.MasterRegionType == RegionTypeEnum.Selection)
                    {
                        if (sp.BasePartCreationIds == null || sp.BasePartCreationIds.Length == 0)
                            throw new CaeException("The base part region must contain at least one item.");
                        //
                        //else if (sp.BasePartCreationIds.Count() != 1)
                        //    throw new CaeException("The base part region can only contain a single part.");
                        //
                        foreach (var geometryId in sp.BasePartCreationIds)
                        {
                            basePart = _controller.Model.Mesh.GetPartFromGeometryId(geometryId);
                            if (basePart.PartType != PartType.Solid)
                                throw new CaeException("The base part region can only contain a solid part.");
                        }
                    }
                    else if (sp.BasePartRegionType == RegionTypeEnum.PartName)
                    {
                        basePart = _controller.Model.Mesh.Parts[sp.BasePartRegionName];
                    }
                    // Tetrahedrons only
                    HashSet<Type> tetraTypes = new HashSet<Type>();
                    tetraTypes.Add(typeof(LinearTetraElement));
                    tetraTypes.Add(typeof(ParabolicTetraElement));
                    if (((MeshPart)basePart).ElementTypes.Except(tetraTypes).Count() != 0)
                        throw new CaeException("The base part region can only contain tetrahedral mesh elements.");
                }
            }
            catch (Exception ex)
            {
                if (throwExceptions) throw ex;
            }
        }
public override void SetSelection(int[] ids,Selection source=null,string prefix="") {
 ValidateSelection(source,prefix);
 if(prefix=="Base part") {SplitPartMeshData.BasePartCreationIds=ids;SplitPartMeshData.BasePartCreationData=CopySelection(source);SplitPartMeshData.BasePartRegionType=RegionTypeEnum.Selection;
 CheckBasePartMeshData(true,out var part);var mp=_controller.GetPartDefaultMeshingParameters(part.Name);SplitPartMeshData.MaxH=mp.MaxH;SplitPartMeshData.MinH=mp.MinH;SplitPartMeshData.Hausdorff=_controller.GetPartDefaultShellMmg(part.Name).Hausdorff;}
 else {SplitPartMeshData.SplitterSurfaceCreationIds=ids;SplitPartMeshData.SplitterSurfaceCreationData=CopySelection(source);SplitPartMeshData.SplitterSurfaceRegionType=RegionTypeEnum.Selection;}Changed();
}
public override void Preview(){CheckSplitPartMeshData(true,out _);_controller.PreviewSplitPartMeshUsingSurface(SplitPartMeshData);}

public override object Item=>SplitPartMeshData;
protected override void OnSelect(object value) {  }
public override string[] SelectionPrefixes=>["Base part","Splitter surface"];
}

// Source PrePoMax/Forms/23_Element/FrmElementQuality.cs SHA256 7d3cf7be626188d5031c3fbb09a13195715880c539a283a4e454f2f7349a7071
public sealed class FrmElementQualityRule : GeometryFormRule {
ViewElementQuality _viewElementQuality;string[] _partNames;Dictionary<int,double> _elementQualities;
public FrmElementQualityRule(Controller controller,string name=null,string[] parts=null):base(controller,null) { _partNames=parts;_viewElementQuality=new ViewElementQuality();SelectedObject=_viewElementQuality; }
protected override void OnApply(bool onOkAddNew)
        {
            // An element set shares its name space with the parts and the other mesh entities, since a part is
            // written to the solver input as an element set of its name
            string name = _controller.GetAllMeshEntityNames().GetNextNumberedKey("Element_qualities");
            bool largerThan = _viewElementQuality.HighlightCriteria == GmshElementQualityHighlightCriteriaEnum.Larger;
            //
            _controller.CreateElementSetFromElementQualityCommand(name, _viewElementQuality.ElementQualityMetric.ToString(),
                                                                  _partNames, largerThan, _viewElementQuality.HighlightLimit);
            //
            /* Dialog lifetime belongs to Qt. */
        }private void GetElementQuality()
        {
            _elementQualities = _controller.GetElementQuality(_viewElementQuality.ElementQualityMetric.ToString(), _partNames);
            double[] sorted = _elementQualities.Values.ToArray();
            Array.Sort(sorted);
            //
            double min;
            double max;
            double average = 0;
            double standardDeviation = 0;
            double limit;
            //
            min = sorted[0];
            max = sorted[sorted.Length - 1];
            foreach (var entry in _elementQualities) average += entry.Value;
            average /= _elementQualities.Count;
            foreach (var entry in _elementQualities) standardDeviation += Math.Pow(entry.Value - average, 2);
            standardDeviation /= _elementQualities.Count;
            standardDeviation = Math.Sqrt(standardDeviation);
            //
            double ratio;
            if (_viewElementQuality.HighlightCriteria == GmshElementQualityHighlightCriteriaEnum.Smaller) ratio = 0.05;
            else ratio = 1 - 0.05;
            //
            limit = sorted[(int)(sorted.Length * ratio)];
            //
            _viewElementQuality.SetValues(min, max, average, standardDeviation, limit);
            ; /* Toolkit presentation. */
            //
            HighlightElements();
        }private void HighlightElements()
        {
            _controller.ClearAllSelection();
            //
            if (_elementQualities == null) return;
            //
            List<int> elementIds = new List<int>();
            if (_viewElementQuality.HighlightCriteria == GmshElementQualityHighlightCriteriaEnum.Smaller)
            {
                foreach (var entry in _elementQualities)
                {
                    if (entry.Value < _viewElementQuality.HighlightLimit) elementIds.Add(entry.Key);
                }
            }
            else if (_viewElementQuality.HighlightCriteria == GmshElementQualityHighlightCriteriaEnum.Larger)
            {
                foreach (var entry in _elementQualities)
                {
                    if (entry.Value > _viewElementQuality.HighlightLimit) elementIds.Add(entry.Key);
                }
            }
            //
            if (elementIds.Count > 0) _controller.HighlightElements(elementIds.ToArray());
        }
public override void Preview()=>GetElementQuality();

public override object Item=>_viewElementQuality;
protected override void OnSelect(object value) {  }
public override string[] SelectionPrefixes=>[];
}
